--Insert columns
ALTER TABLE TRIALS.TBL_TIPO_AUDIENCIA
ADD COLUMN FN_MATERIA INT,
ADD COLUMN FN_TIPO_SISTEMA INT;

ALTER TABLE TRIALS.TBL_TIPO_AUDIENCIA
ADD CONSTRAINT FK_MATERIA
FOREIGN KEY (FN_MATERIA) REFERENCES TRIALS.TBL_MATERIAS (PN_ID),
ADD CONSTRAINT FK_TIPO_SISTEMA
FOREIGN KEY (FN_TIPO_SISTEMA) REFERENCES TRIALS.TBL_TIPO_SISTEMA (PN_ID);

CREATE INDEX IF NOT EXISTS IDX_MATERIA_TIPO_AUDIENCIA ON TRIALS.TBL_TIPO_AUDIENCIA (FN_MATERIA);
CREATE INDEX IF NOT EXISTS IDX_TIPO_SISTEMA_TIPO_AUDIENCIA ON TRIALS.TBL_TIPO_AUDIENCIA (FN_TIPO_SISTEMA);

